{
  "segment_function": "definition",
  "claims": [
    {
      "claim": "The vita activa is designated by three fundamental human activities: labor, work, and action, each corresponding to a basic condition under which life on earth is given.",
      "claim_type": "author_position",
      "supporting_excerpt": "With the term vita activa , I propose to designate three fundamental human activities: labor, work, and action. They are fundamental because each corresponds to one of the basic conditions under which life on earth has been given to man.",
      "support_kind": "direct",
      "qualifications": [],
      "confidence": 1
    },
    {
      "claim": "Action has the closest connection with the human condition of natality because the new beginning inherent in birth is actualized through the newcomer's capacity for action.",
      "claim_type": "author_position",
      "supporting_excerpt": "However, of the three, action has the closest connection with the human condition of natality; the new beginning inherent in birth can make itself felt in the world only because the newcomer possesses the capacity of beginning something anew, that is, of acting.",
      "support_kind": "direct",
      "qualifications": [],
      "confidence": 1
    }
  ],
  "definitions": [
    {
      "term": "Labor",
      "definition": "The activity corresponding to the biological process of the human body, bound to vital necessities and having life itself as its human condition."
    },
    {
      "term": "Work",
      "definition": "The activity corresponding to the unnaturalness of human existence, providing an artificial world of things with the human condition of worldliness."
    },
    {
      "term": "Action",
      "definition": "The only activity going on directly between men without intermediaries, corresponding to the human condition of plurality."
    }
  ],
  "distinctions": [
    {
      "item_a": "Labor",
      "item_b": "Work",
      "distinction": "Labor corresponds to the biological life process and species survival, whereas work provides an artificial world of durable things distinct from natural surroundings."
    }
  ],
